"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { ArrowLeftIcon, ArrowRightIcon } from "lucide-react";

const tips = [
	{
		title: "Welcome to Dashboard",
		description:
			"This is your new workspace. Here you'll find all your projects, recent activities, settings, and more.",
	},
	{
		title: "Quick Actions",
		description:
			"Use the toolbar above to create new projects, invite team members, or access settings.",
	},
	{
		title: "Need Help?",
		description:
			"Click the support icon in the top right corner to access our help center and documentation.",
	},
	{
		title: "Keyboard Shortcuts",
		description:
			"Press ⌘K to open the command palette. Use arrow keys to navigate and Enter to select an action.",
	},
	{
		title: "Stay Updated",
		description:
			"Enable notifications to receive updates about your projects, team activity, and important deadlines.",
	},
];

export default function Component() {
	const [currentTip, setCurrentTip] = useState(0);

	const handleNext = () => {
		if (currentTip < tips.length - 1) {
			setCurrentTip(currentTip + 1);
		}
	};

	const handlePrev = () => {
		if (currentTip > 0) {
			setCurrentTip(currentTip - 1);
		}
	};

	const isFirstTip = currentTip === 0;
	const isLastTip = currentTip === tips.length - 1;

	return (
		<Popover>
			<PopoverTrigger asChild>
				<Button variant="outline">Tooltip-like with nav</Button>
			</PopoverTrigger>
			<PopoverContent className="max-w-[280px] py-3 shadow-none" side="top">
				<div className="space-y-3">
					<div className="space-y-1">
						<p className="text-[13px] font-medium">
							{tips[currentTip].title}
						</p>
						<p className="text-muted-foreground text-xs">
							{tips[currentTip].description}
						</p>
					</div>
					<div className="flex items-center justify-between">
						<span className="text-muted-foreground text-xs">
							{currentTip + 1}/{tips.length}
						</span>
						<div className="flex gap-0.5">
							<Button
								size="icon"
								variant="ghost"
								className="size-6"
								onClick={handlePrev}
								disabled={isFirstTip}
								aria-label="Previous tip"
							>
								<ArrowLeftIcon size={14} aria-hidden="true" />
							</Button>
							<Button
								size="icon"
								variant="ghost"
								className="size-6"
								onClick={handleNext}
								disabled={isLastTip}
								aria-label="Next tip"
							>
								<ArrowRightIcon size={14} aria-hidden="true" />
							</Button>
						</div>
					</div>
				</div>
			</PopoverContent>
		</Popover>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
